def make(i, row):
    tag, prompt, options, answer, reason = row
    opts = [{"id": chr(65+j), "text": t} for j, t in enumerate(options)]
    aid = next(o["id"] for o in opts if o["text"] == answer)
    refs = [{"url": u, "title": t + "；僅研究題型與能力方向，未複製原題。", "year": "113-114", "subject": "social", "locator": loc, "observedPattern": "公開社會科農業生產、自然條件與資料推理題的能力結構，經本題重新設計", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for u, t, loc in SOURCES]
